<script setup lang="ts">
import { imageIndexAtPath } from '~/utils/image-slots'
import { useEditorReturn } from '~/composables/useEditorReturn'
import { ArrowLeft, MousePointer2, Save, History, Code2, Undo2, Redo2, Sparkles, ArrowUpRight, Copy } from 'lucide-vue-next'
import { elementInfo, patchElement, sanitizeHtml, prepareComponent, extractFieldValues, categories, type Resource, type ComponentData } from '@qinbian/shared'
const inspectMode=ref(false),inspectedPath=ref<number[]|undefined>(),inspectedComputed=ref<Record<string,string>>({}),canvas=ref<any>(),aiBusy=ref(false)
const inspected=computed(()=>inspectedPath.value?elementInfo(html.value,inspectedPath.value):null)
function toggleInspect(){if(aiBusy.value)return;inspectMode.value=!inspectMode.value;inspectedPath.value=undefined;panel.value=inspectMode.value?'inspect':'properties'}
function inspectElement(path:number[],computed:Record<string,string>,activate=true){if(!activate){inspectedComputed.value=computed;return}if(aiBusy.value)return;inspectedPath.value=[...path];inspectedComputed.value=computed;if(panel.value!=='ai')panel.value='inspect'}
function patchInspected(patch:any){if(!inspected.value)return;try{update(patchElement(html.value,inspected.value,patch));void nextTick(()=>canvas.value?.inspectAt(inspectedPath.value))}catch(e){ctx.error(e)}}
function editInspectedText(){const path=inspectedPath.value;inspectMode.value=false;panel.value='properties';void nextTick(()=>canvas.value?.editAt(path))}
function inspectMedia(){if(inspectedPath.value)mediaIndex.value=imageIndexAtPath(html.value,inspectedPath.value);panel.value='properties'}
function setAiBusy(value:boolean){aiBusy.value=value}
function inspectParent(path:number[]){canvas.value?.inspectAt(path)}
const bindingsEditor=ref<{focusField:(id:string)=>void}>()
function focusDataField(id:string){panel.value='properties';void nextTick(()=>bindingsEditor.value?.focusField(id))}
const returnTo=useEditorReturn('/resources')
const backLabel=computed(()=>returnTo.value.startsWith('/documents/')?'返回文章':'返回资源列表')
const props=defineProps<{resource:Resource}>(),emit=defineEmits<{refresh:[]}>(),ctx=useQinbian()
const initial=structuredClone(toRaw(props.resource));initial.data=prepareComponent(initial.data)
const item=ref<Resource>(initial),html=ref(item.value.data.html||''),tags=ref(item.value.tags.join('，')),width=ref(375),panel=ref<'properties'|'ai'|'inspect'>('properties'),editor=shallowRef<any>(null),mediaIndex=ref(0),saving=ref(false),status=ref('已保存在本机'),codeOpen=ref(false),code=ref(''),versionsOpen=ref(false),versions=ref<any[]>([]),history=ref<string[]>([JSON.stringify(item.value.data)]),historyAt=ref(0)
let timer:ReturnType<typeof setTimeout>|undefined,pending:Promise<void>|undefined
const payload=()=>({name:item.value.name,description:item.value.description,category:item.value.category,themeSetId:item.value.themeSetId,kind:'component',tags:tags.value.split(/[,，]/).map(s=>s.trim()).filter(Boolean),data:{...item.value.data,html:html.value}})
let saved=JSON.stringify(payload())
function queue(){if(item.value.builtin)return;status.value='尚未保存';localStorage.setItem('qinbian-resource-'+item.value.id,JSON.stringify({...payload(),revision:item.value.revision}));clearTimeout(timer);timer=setTimeout(()=>void save().catch(()=>{}),700)}
function commitData(next:ComponentData){if(JSON.stringify(next)===JSON.stringify(item.value.data))return;item.value.data=next;html.value=next.html||'';const snapshot=JSON.stringify(next);history.value=history.value.slice(0,historyAt.value+1);history.value.push(snapshot);if(history.value.length>100)history.value.shift();historyAt.value=history.value.length-1;queue()}
function updateSettings(data:ComponentData){commitData(prepareComponent(data))}
function update(value:string){const cleaned=sanitizeHtml(value);if(cleaned===html.value)return;const data={...item.value.data,html:cleaned,values:{...item.value.data.values,...extractFieldValues(cleaned,item.value.data.fields||[])}};commitData(cleaned.includes('data-qb-chart')?prepareComponent(data):data)}
function applyHistory(){item.value.data=JSON.parse(history.value[historyAt.value]!);html.value=item.value.data.html||'';queue()}
function undo(){if(historyAt.value>0){historyAt.value--;applyHistory()}};function redo(){if(historyAt.value<history.value.length-1){historyAt.value++;applyHistory()}}
async function save(){clearTimeout(timer);if(item.value.builtin)return;if(pending){await pending;return save()}const snap=JSON.stringify(payload());if(snap===saved)return;const body={...JSON.parse(snap),revision:item.value.revision};saving.value=true;status.value='正在保存…';pending=(async()=>{try{const r=await apiFetch<Resource>('/api/resources/'+item.value.id,{method:'PUT',body});item.value.revision=r.revision;item.value.updatedAt=r.updatedAt;saved=snap;if(JSON.stringify(payload())===saved){status.value='已保存在本机';localStorage.removeItem('qinbian-resource-'+item.value.id)}else queue()}catch(e){status.value='保存未成功 · 已留本地副本';ctx.error(e);throw e}finally{saving.value=false;pending=undefined}})();await pending;if(JSON.stringify(payload())!==saved)return save()}
async function clone(){try{const r=await apiFetch<Resource>('/api/resources/'+item.value.id+'/clone',{method:'POST',body:{themeSetId:'mine'}});navigateTo({path:'/resources/'+r.id,query:{returnTo:returnTo.value}})}catch(e){ctx.error(e)}}
async function startArticle(){try{await save();const d=await apiFetch<any>('/api/documents',{method:'POST',body:{resourceId:item.value.id}});navigateTo('/documents/'+d.id)}catch(e){ctx.error(e)}}
async function versionsList(){await save().catch(()=>{});try{versions.value=await apiFetch<any[]>('/api/resources/'+item.value.id+'/versions');versionsOpen.value=true}catch(e){ctx.error(e)}}
function adopt(r:Resource){item.value=r;html.value=r.data.html||'';tags.value=r.tags.join('，');history.value=[JSON.stringify(r.data)];historyAt.value=0;saved=JSON.stringify(payload());status.value='已保存在本机'}
async function restore(v:any){if(!confirm('恢复这一版组件？当前版本会保留。'))return;try{adopt(await apiFetch<Resource>(`/api/resources/${item.value.id}/versions/${v.revision}/restore`,{method:'POST',body:{revision:item.value.revision}}));versionsOpen.value=false;ctx.notify('组件已恢复')}catch(e){ctx.error(e)}}
async function applied(result:any){if(result.value.id===item.value.id)adopt(result.value);else ctx.notify('新组件已保存，可在文章中插入')}
onMounted(()=>{const cache=localStorage.getItem('qinbian-resource-'+item.value.id);if(cache){try{const c=JSON.parse(cache);if(confirm('发现这枚组件尚未保存的本地副本，要恢复继续编辑吗？')){const revision=item.value.revision;item.value={...item.value,...c,revision};html.value=c.data.html;tags.value=c.tags.join('，');queue()}else localStorage.removeItem('qinbian-resource-'+item.value.id)}catch{}}})
onBeforeRouteLeave(async()=>{try{await save();return true}catch{return confirm('改动已留在本地副本中。仍要离开吗？')}});onBeforeUnmount(()=>clearTimeout(timer))
</script>
<template><div class="component-studio"><header class="workbench-heading"><NuxtLink :to="returnTo" class="icon-button" :aria-label="backLabel"><ArrowLeft :size="19"/></NuxtLink><div class="workbench-title"><input v-model="item.name" :readonly="item.builtin" aria-label="组件名称" @input="queue"><span>{{item.builtin?'内置组件 · 原件只读':status}}</span></div><div class="workbench-actions"><button class="icon-button" :class="{active:inspectMode}" aria-label="点选元素" :aria-pressed="inspectMode" :disabled="item.builtin||aiBusy" @click="toggleInspect"><MousePointer2 :size="17"/></button><button class="icon-button" aria-label="撤销组件修改" :disabled="historyAt===0" @click="undo"><Undo2 :size="17"/></button><button class="icon-button" aria-label="重做组件修改" :disabled="historyAt>=history.length-1" @click="redo"><Redo2 :size="17"/></button><button class="icon-button" aria-label="组件历史版本" @click="versionsList"><History :size="17"/></button><button class="btn" @click="startArticle"><ArrowUpRight :size="15"/><span>编成文章</span></button><button v-if="item.builtin" class="btn primary" @click="clone"><Copy :size="15"/>编辑副本</button><button v-else class="btn primary" :disabled="saving" @click="save().catch(()=>{})"><Save :size="15"/>保存组件</button></div></header>
 <div class="studio-columns"><aside class="studio-meta"><p class="eyebrow">组件资料</p><h3>给版式一个名字</h3><div class="form-stack"><label>所属套组<UiSelect v-model="item.themeSetId" :options="ctx.themes.value.filter(t=>!t.builtin||t.id===item.themeSetId).map(t=>({value:t.id,label:t.name}))" :disabled="item.builtin" aria-label="所属套组" @change="queue"/></label><label>内容分类<UiSelect v-model="item.category" :options="[...new Set([item.category,...categories])].map(c=>({value:c,label:c}))" :disabled="item.builtin" aria-label="内容分类" @change="queue"/></label><label>用途说明<textarea v-model="item.description" rows="3" :readonly="item.builtin" @input="queue"/></label><label>标签<input v-model="tags" :readonly="item.builtin" placeholder="用逗号隔开" @input="queue"></label></div><div class="quiet-note">一枚组件，只表达一件清楚的事。<br>留白、层级与配色，让文字慢慢展开。</div><button class="text-button" @click="code=html;codeOpen=true"><Code2 :size="14"/>查看与编辑源码</button></aside>
 <section class="studio-paper-area"><RichToolbar :editor="editor" :palette="item.data.palette" :mappings="item.data.colorMappings"/><div class="paper-options"><div class="preview-width-tabs"><button v-for="w in [320,375,414]" :key="w" :class="{active:width===w}" @click="width=w">{{w}}</button></div><span>点文字改写 · 点图片替换</span></div><div class="canvas-paper single-component" :style="{width:width+'px'}"><CanvasBlock ref="canvas" :html="html" :inspect="inspectMode" :inspected-path="inspectedPath" @inspect="inspectElement" @inspect-exit="toggleInspect" selected :readonly="item.builtin" @update="update" @editor="e=>editor=e" @field="focusDataField" @media="n=>{mediaIndex=n;panel='properties'}"/></div><p class="canvas-footnote">组件的外层设计会保留，文字与图片可以自由替换。</p></section>
 <aside class="studio-right"><div class="mini-tabs"><button v-if="inspectMode" :class="{active:panel==='inspect'}" @click="panel='inspect'">点选属性</button><button :class="{active:panel==='properties'}" @click="panel='properties'">组件设置</button><button :class="{active:panel==='ai'}" @click="panel='ai'"><Sparkles :size="13"/>AI 制作</button></div><ComponentBindings ref="bindingsEditor" v-if="panel==='properties'&&!item.builtin" :data="item.data" :theme-set-id="item.themeSetId" @update="updateSettings"/><MediaInspector v-if="panel==='properties'&&!item.builtin" :html="html" :legacy-id="item.legacyId" :media-index="mediaIndex" @update="update"/><p v-else-if="panel==='properties'" class="small muted">先另存一份副本，即可自由编辑这枚组件。</p><ElementInspector v-if="panel==='inspect'" :info="inspected" :computed-styles="inspectedComputed" :palette="item.data.palette" :mappings="item.data.colorMappings" :fields="item.data.fields" @select="inspectParent" @patch="patchInspected" @ai="panel='ai'" @edit-text="editInspectedText" @media="inspectMedia"/><AiPanel v-show="panel==='ai'" :theme-set-id="item.themeSetId" target-type="resource" :target-id="item.id" :target-revision="item.revision" :source-html="inspectMode&&inspected?inspected.html:html" :selection="inspectMode&&inspected?{path:inspected.path,fingerprint:inspected.fingerprint}:undefined" :settings="item.data" :before-start="save" @busy="setAiBusy" @applied="applied"/></aside></div>
 <UiModal v-if="codeOpen" title="组件源码" subtitle="高级编辑会经过同一套正文规则检查。" wide @close="codeOpen=false"><textarea v-model="code" :readonly="item.builtin" class="source-editor" rows="18" spellcheck="false"/><div class="modal-actions"><button v-if="!item.builtin" class="btn primary" @click="update(code);codeOpen=false">应用修改</button></div></UiModal>
 <UiModal v-if="versionsOpen" title="组件历史版本" @close="versionsOpen=false"><div class="version-list"><div v-for="v in versions" :key="v.id"><span>第 {{v.revision}} 版<small>{{formatDate(v.createdAt)}}</small></span><button class="btn" :disabled="v.revision===item.revision||item.builtin" @click="restore(v)">{{v.revision===item.revision?'当前版本':'恢复'}}</button></div><p v-if="!versions.length" class="muted">还没有编辑历史。</p></div></UiModal>
</div></template>
